package Client;

// this file is Test case generated by GPT

import Server.Interface.IResourceManager;

import java.rmi.registry.LocateRegistry;
import java.rmi.registry.Registry;
import java.util.Arrays;
import java.util.Vector;
import java.util.concurrent.CountDownLatch;

public class RMITestClient {
    private static final String PREFIX = "group_18_";

    private static void check(boolean condition, String description) {
        if (!condition) {
            throw new AssertionError("FAILED: " + description);
        }
        System.out.println("PASS: " + description);
    }

    private static Vector<String> flights(int... numbers) {
        Vector<String> result = new Vector<>();
        for (int number : numbers) {
            result.add(String.valueOf(number));
        }
        return result;
    }

    public static void main(String[] args) throws Exception {
        String host = args.length > 0 ? args[0] : "localhost";
        Registry registry = LocateRegistry.getRegistry(host, 1099);
        IResourceManager rm =
            (IResourceManager) registry.lookup(PREFIX + "Middleware");

        // 每次运行使用不同编号，避免碰到上一次测试留在 RM 内存中的数据。
        int base = (int) (System.nanoTime() & 0x3fffffff);
        int flight = base + 10;
        int bundleFlight = base + 11;
        int raceFlight = base + 12;
        int customer = base + 20;
        int bundleCustomer = base + 21;
        int raceCustomerA = base + 22;
        int raceCustomerB = base + 23;
        String location = "test-" + base;

        System.out.println("Test prefix: " + base);

        // 1. 添加、重复添加、价格更新。
        check(rm.addFlight(flight, 2, 100), "add flight");
        check(rm.addFlight(flight, 1, 120), "add seats and update price");
        check(rm.queryFlight(flight) == 3, "flight has 3 available seats");
        check(rm.queryFlightPrice(flight) == 120, "flight price is 120");

        // 2. 客户、单项预订、账单、删除客户和归还库存。
        check(rm.newCustomer(customer), "create customer");
        check(!rm.newCustomer(customer), "reject duplicate customer");
        check(rm.reserveFlight(customer, flight), "reserve one flight seat");
        check(rm.queryFlight(flight) == 2, "reservation decreases availability");
        check(!rm.deleteFlight(flight), "cannot delete reserved flight");

        String bill = rm.queryCustomerInfo(customer);
        check(bill.contains("flight-" + flight), "bill contains flight");
        check(bill.contains("Total: $120"), "bill has correct total");

        check(rm.deleteCustomer(customer), "delete customer");
        check(rm.queryFlight(flight) == 3, "deletion restores flight seat");
        check(rm.queryCustomerInfo(customer).isEmpty(), "customer is gone");
        check(rm.deleteFlight(flight), "delete unreserved flight");

        // 3. Bundle：同一航班号出现两次，需占用两个座位。
        check(rm.newCustomer(bundleCustomer), "create bundle customer");
        check(rm.addFlight(bundleFlight, 2, 50), "add bundle flight");
        check(rm.addCars(location, 1, 30), "add car");
        check(rm.addRooms(location, 1, 40), "add room");

        check(!rm.bundle(bundleCustomer,
                flights(bundleFlight, bundleFlight, bundleFlight),
                location, true, true),
            "bundle fails when 3 seats are requested but only 2 exist");
        check(rm.queryFlight(bundleFlight) == 2
                && rm.queryCars(location) == 1
                && rm.queryRooms(location) == 1,
            "failed precheck leaves all inventory unchanged");

        check(rm.bundle(bundleCustomer,
                flights(bundleFlight, bundleFlight),
                location, true, true),
            "bundle reserves 2 seats, car, and room");
        check(rm.queryFlight(bundleFlight) == 0
                && rm.queryCars(location) == 0
                && rm.queryRooms(location) == 0,
            "bundle updates all three inventories");

        bill = rm.queryCustomerInfo(bundleCustomer);
        check(bill.contains("Total: $170"), "bundle total is 2*50+30+40");

        check(rm.deleteCustomer(bundleCustomer), "delete bundle customer");
        check(rm.queryFlight(bundleFlight) == 2
                && rm.queryCars(location) == 1
                && rm.queryRooms(location) == 1,
            "deleting bundle customer restores all inventory");

        // 4. 两个客户端请求同时争抢最后一个座位。
        check(rm.newCustomer(raceCustomerA), "create race customer A");
        check(rm.newCustomer(raceCustomerB), "create race customer B");
        check(rm.addFlight(raceFlight, 1, 70), "add one race seat");

        CountDownLatch start = new CountDownLatch(1);
        boolean[] results = new boolean[2];
        Throwable[] errors = new Throwable[2];

        Thread a = new Thread(() -> {
            try {
                start.await();
                results[0] = rm.reserveFlight(raceCustomerA, raceFlight);
            } catch (Throwable e) {
                errors[0] = e;
            }
        });
        Thread b = new Thread(() -> {
            try {
                start.await();
                results[1] = rm.reserveFlight(raceCustomerB, raceFlight);
            } catch (Throwable e) {
                errors[1] = e;
            }
        });

        a.start();
        b.start();
        start.countDown();
        a.join();
        b.join();

        check(errors[0] == null && errors[1] == null,
            "both concurrent calls completed without exceptions");
        check(results[0] != results[1],
            "exactly one customer reserved the last seat");
        check(rm.queryFlight(raceFlight) == 0,
            "no seat remains and inventory did not become negative");

        System.out.println("ALL RMI CHECKS PASSED");
    }
}

